def number(token):
    # The retained original remains exact. A float projection must round-trip
    # its decimal token; underflow or lost digits mean unavailable, not zero.
    if len(token)>512:raise ValueError('Context numeric token exceeds bound')
    try:
        exact=Decimal(token);value=float(token)
    except (ValueError,InvalidOperation,OverflowError):
        raise ValueError('Invalid context number') from None
    if not exact.is_finite() or not math.isfinite(value):raise ValueError('Nonfinite context number')
    if Decimal(str(value))!=exact:raise ValueError('Lossy context numeric projection')
    return value
